document.getElementById("btn-reboot").addEventListener("click",(async function(e){e.preventDefault();new bootstrap.Modal(document.getElementById("modal-reboot")).show();try{await fetch("/api/reboot",{method:"POST"});const e=async()=>{try{const t=new AbortController,o=setTimeout((()=>t.abort()),800),r=await fetch("/api/info",{signal:t.signal});if(clearTimeout(o),r.ok){bootstrap.Modal.getInstance(document.getElementById("modal-reboot")).hide(),location.reload()}else console.error("Device is not reachable yet"),setTimeout(e,1e3)}catch(t){console.error("Error checking device status:",t),setTimeout(e,1e3)}};setTimeout(e,1e3)}catch(e){console.error("Error rebooting device:",e)}}));